/* Câu hỏi các đề Công nghệ lớp 6 có sẵn. Danh mục (tên, khối, môn, số phút, số câu): data/banks/index.js.
   App chỉ tải file này khi mở một đề trong đó. Dạng câu hỏi: xem đầu data/banks/index.js. */
window.ONTAP_SEED_QUESTIONS = Object.assign(window.ONTAP_SEED_QUESTIONS || {}, {
  /* ---------- Công nghệ 6 · Kiểm tra cuối học kì I (Kết nối tri thức) ----------
     Phạm vi học kì I ghi ở note. Câu tự soạn. Mức độ lv của đề 1 ghi ở Phiên N6 (câu, chủ đề giữ nguyên). Phiên DS7 dò Chương I
     với sách in năm 2026 (Bài 1 Khái quát về nhà ở, Bài 2 Xây dựng nhà ở, Bài 3 Ngôi nhà thông minh; mục III của Bài 3 là sử dụng
     năng lượng tiết kiệm và hiệu quả): chủ đề theo tên bài, câu về chất đốt, gas, than soạn lại vì sách không dạy, giữ mức và
     dạng câu. Hai đề là kho của đề ngẫu nhiên "congnghe6-ck1-ngau-nhien" (không có câu riêng nên không ghi vào file này; ma trận
     ở data/banks/index.js). Câu ở hai ô khác nhau của ma trận có thể cùng được rút vào một đề, nên đề bài, các lựa chọn, lời giải
     không ghi sẵn đáp án của câu khác. Cách xếp mức (cả hai đề): nêu vai trò, bộ phận, vật liệu, nguồn năng lượng, phương pháp,
     nhóm thực phẩm là Biết; phân loại, giải thích, đánh giá một nhận định, sắp xếp các bước bảo quản theo quy trình đã học là
     Hiểu; xử lí tình huống trong gia đình, chọn cách làm, tính chi phí và lượng thực phẩm, sắp xếp các bước làm một món ăn là Vận dụng. */
  "congnghe6-ck1-de1": {
    note: "Sách Kết nối tri thức, học kì I: Chương I Nhà ở (Bài 1 Khái quát về nhà ở, Bài 2 Xây dựng nhà ở, Bài 3 Ngôi nhà thông minh); Chương II Bảo quản và chế biến thực phẩm (Bài 4 Thực phẩm và dinh dưỡng, Bài 5 Phương pháp bảo quản và chế biến thực phẩm, Bài 6 Dự án Bữa ăn kết nối yêu thương). Trường nào học thêm Chương III Trang phục và thời trang trong học kì I thì cần ôn thêm phần đó. Có lời giải từng câu.",
    questions: [
      { topic: "Khái quát về nhà ở", type: "mc", q: "Vai trò của nhà ở đối với con người là:", o: ["Là nơi ở, bảo vệ con người trước thiên nhiên và đáp ứng nhu cầu sinh hoạt", "Chỉ là nơi cất giữ đồ đạc, tài sản quý giá của các thành viên trong gia đình", "Là nơi làm việc của các cơ quan nhà nước", "Chỉ để thể hiện sự giàu có của chủ nhà"], x: "Nhà ở là nơi ở, bảo vệ con người trước nắng, mưa, gió, bão… và đáp ứng nhu cầu sinh hoạt hằng ngày như ăn, ngủ, nghỉ ngơi, học tập.", lv: 1 },
      { topic: "Khái quát về nhà ở", type: "mc", q: "Bộ phận nào của ngôi nhà nằm dưới mặt đất, đỡ toàn bộ ngôi nhà?", o: ["Móng nhà", "Mái nhà", "Tường nhà", "Cửa sổ"], x: "Móng nhà nằm sâu dưới đất, chịu toàn bộ sức nặng của ngôi nhà. Mái nhà che mưa nắng; tường bao quanh nhà và ngăn chia các phòng.", lv: 1 },
      { topic: "Khái quát về nhà ở", type: "mc", q: "Kiểu nhà nào thường gặp ở vùng núi nước ta?", o: ["Nhà sàn", "Nhà nổi", "Nhà chung cư", "Nhà mặt phố"], x: "Nhà sàn dựng trên các cột, hợp với địa hình và tập quán sinh hoạt ở vùng cao. Nhà nổi có ở vùng sông nước; nhà chung cư, nhà mặt phố có nhiều ở thành phố.", lv: 1 },
      { topic: "Khái quát về nhà ở", type: "mc", q: "Vì sao nhà ở mỗi vùng của nước ta có kiến trúc khác nhau?", o: ["Vì nhà ở phụ thuộc vào vị trí địa lí, khí hậu, kinh tế, văn hoá, xã hội của từng nơi", "Vì mỗi vùng chỉ có đúng một loại vật liệu xây dựng", "Vì người dân muốn nhà mình khác nhà hàng xóm", "Vì mỗi vùng chỉ được xây một kiểu nhà duy nhất"], x: "Nhà ở mang tính vùng miền: kiến trúc phụ thuộc vào vị trí địa lí, khí hậu, kinh tế, văn hoá, xã hội của nơi đó.", lv: 1 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Nhóm nào gồm toàn vật liệu có sẵn trong tự nhiên dùng để làm nhà?", o: ["Tre, gỗ, lá, cát, đá", "Gạch, ngói, xi măng", "Xi măng, thép, kính, sơn", "Gạch, ngói, tre, gỗ"], x: "Tre, gỗ, lá, cát, đá có sẵn trong tự nhiên. Gạch, ngói, xi măng, thép, kính, sơn là vật liệu nhân tạo do con người sản xuất.", lv: 2 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Các bước chính để xây dựng một ngôi nhà, theo đúng thứ tự, là:", o: ["Thiết kế → Thi công thô → Hoàn thiện", "Thi công thô → Thiết kế → Hoàn thiện", "Hoàn thiện → Thiết kế → Thi công thô", "Thiết kế → Hoàn thiện → Thi công thô"], x: "Xây dựng nhà ở gồm ba bước chính: thiết kế (hình dung ngôi nhà, chuẩn bị vật liệu, kinh phí) → thi công thô (làm móng, khung, tường, mái…) → hoàn thiện (trát, sơn tường, lát nền, lắp thiết bị điện, nước, nội thất).", lv: 1 },
      { topic: "Xây dựng nhà ở", type: "tf", q: "Người kĩ sư xây dựng có thể làm bản thiết kế và giám sát thợ thi công để ngôi nhà được xây đúng thiết kế.", a: true, x: "Đúng. Công việc chính của kĩ sư xây dựng là thiết kế, tổ chức thi công, kiểm tra và giám sát quá trình thi công để công trình đúng thiết kế.", lv: 1 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Ngôi nhà thông minh là ngôi nhà:", o: ["Có hệ thống điều khiển tự động hoặc bán tự động các đồ dùng trong nhà", "Có thật nhiều phòng, nhiều tầng và đầy đủ các đồ đạc, máy móc đắt tiền", "Được xây ở trung tâm thành phố, gần trường học, bệnh viện, siêu thị lớn", "Chỉ cần có máy tính và điện thoại thông minh"], x: "Ngôi nhà thông minh có hệ thống điều khiển tự động hoặc bán tự động các đồ dùng (đèn, điều hòa, camera, rèm cửa…), có thể điều khiển từ xa bằng điện thoại.", lv: 1 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Chủ nhà nói “Tắt đèn phòng khách”, đèn liền tắt; đến giờ đi ngủ, đèn phòng ngủ tự dịu bớt. Đây là chức năng của hệ thống nào trong ngôi nhà thông minh?", o: ["Hệ thống chiếu sáng", "Hệ thống giải trí", "Hệ thống kiểm soát nhiệt độ", "Hệ thống điều khiển các thiết bị gia dụng"], x: "Điều khiển đèn bằng giọng nói, tự điều chỉnh độ sáng theo giờ thuộc hệ thống chiếu sáng thông minh.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Ba đặc điểm của ngôi nhà thông minh là:", o: ["Tiện ích, an ninh an toàn, tiết kiệm năng lượng", "Rộng rãi, nhiều tầng, đắt tiền", "Chỉ dùng năng lượng mặt trời, không dùng điện lưới", "Không cần ai trông nom, không cần sửa chữa"], x: "Ngôi nhà thông minh có ba đặc điểm: tiện ích, an ninh an toàn và tiết kiệm năng lượng.", lv: 1 },
      { topic: "Ngôi nhà thông minh", type: "tf", q: "Trong ngôi nhà thông minh, khi phát hiện khói, chuông báo cháy tự kêu để cảnh báo. Đây là chức năng của hệ thống an ninh, an toàn.", a: true, x: "Báo cháy, báo khói, camera giám sát, khóa cửa thông minh… thuộc hệ thống an ninh, an toàn.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Việc làm nào giúp tiết kiệm điện?", o: ["Tắt đèn, quạt khi ra khỏi phòng", "Mở cửa tủ lạnh nhiều lần và để mở lâu", "Bật đèn cả ngày dù trời đã sáng", "Để ti vi bật khi không có ai xem"], x: "Tắt đồ dùng điện khi không dùng là cách đơn giản để tiết kiệm điện. Mở tủ lạnh lâu, bật đèn ban ngày, để ti vi chạy không đều gây lãng phí điện.", lv: 1 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Khi dùng máy giặt, cách làm nào giúp tiết kiệm điện và nước?", o: ["Gom đủ quần áo rồi giặt một lần thay vì giặt nhiều lần ít đồ", "Giặt riêng từng chiếc áo mỗi khi thay ra", "Luôn chọn chế độ giặt lâu nhất cho mọi lần giặt", "Cho máy chạy thử một lượt không có quần áo trước khi giặt"], x: "Giặt đủ một mẻ giúp giảm số lần máy chạy nên đỡ tốn điện, nước. Dùng đồ dùng đúng cách là một cách sử dụng năng lượng tiết kiệm.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "tf", q: "Năng lượng mặt trời và năng lượng gió là những nguồn năng lượng thân thiện với môi trường.", a: true, x: "Đúng. Ánh sáng mặt trời và gió có sẵn trong tự nhiên, ít gây ô nhiễm; gia đình nên tận dụng các nguồn năng lượng này.", lv: 1 },
      { topic: "Thực phẩm và dinh dưỡng", type: "mc", q: "Nhóm thực phẩm nào giàu chất đạm?", o: ["Thịt, cá, trứng, đậu phụ", "Gạo, ngô, khoai lang, bánh mì", "Dầu ăn, mỡ, bơ", "Rau cải, cà rốt, cam"], x: "Thịt, cá, trứng, sữa, đậu… giàu chất đạm, giúp cơ thể lớn lên và tạo tế bào mới. Gạo, ngô, khoai giàu tinh bột; dầu ăn, mỡ, bơ giàu chất béo; rau quả giàu vitamin và chất khoáng.", lv: 1 },
      { topic: "Thực phẩm và dinh dưỡng", type: "mc", q: "Chất dinh dưỡng nào là nguồn cung cấp năng lượng chủ yếu cho mọi hoạt động của cơ thể?", o: ["Chất tinh bột, chất đường", "Chất khoáng", "Các loại vitamin (A, B, C, D)", "Nước"], x: "Chất tinh bột, chất đường là nguồn cung cấp năng lượng chủ yếu cho cơ thể, có nhiều trong gạo, ngô, khoai, sắn, bánh mì.", lv: 1 },
      { topic: "Thực phẩm và dinh dưỡng", type: "mc", q: "Cơ thể thiếu i-ốt có thể bị bệnh nào?", o: ["Bướu cổ", "Còi xương", "Quáng gà", "Sâu răng"], x: "I-ốt giúp tuyến giáp hoạt động tốt; thiếu i-ốt dễ bị bướu cổ, vì vậy nên dùng muối i-ốt khi nấu ăn. Thiếu canxi, vitamin D dễ bị còi xương; thiếu vitamin A dễ bị quáng gà.", lv: 2 },
      { topic: "Thực phẩm và dinh dưỡng", type: "tf", q: "Bữa ăn hợp lí cần có đủ các nhóm thực phẩm chính với tỉ lệ thích hợp.", a: true, x: "Bữa ăn hợp lí phối hợp nhiều loại thực phẩm, có đủ các nhóm chất dinh dưỡng với tỉ lệ thích hợp.", lv: 1 },
      { topic: "Thực phẩm và dinh dưỡng", type: "tf", q: "Bỏ bữa sáng giúp cơ thể khỏe mạnh hơn vì dạ dày được nghỉ ngơi.", a: false, x: "Bữa sáng cung cấp năng lượng cho cả buổi học. Bỏ bữa sáng dễ làm cơ thể mệt mỏi, khó tập trung và hại dạ dày. Cần ăn đủ ba bữa chính mỗi ngày.", lv: 2 },
      { topic: "Bảo quản và chế biến thực phẩm", type: "mc", q: "Bảo quản thực phẩm nhằm mục đích:", o: ["Làm chậm việc thực phẩm bị hư hỏng, kéo dài thời gian sử dụng", "Làm cho thực phẩm có màu sắc đẹp mắt, hấp dẫn người mua hơn", "Làm tăng khối lượng của thực phẩm", "Làm cho thực phẩm mềm hơn và chín nhanh hơn khi đem đi nấu"], x: "Bảo quản thực phẩm giúp làm chậm quá trình hư hỏng, giữ được chất dinh dưỡng và kéo dài thời gian sử dụng.", lv: 1 },
      { topic: "Bảo quản và chế biến thực phẩm", type: "mc", q: "Phương pháp bảo quản thực phẩm ở nhiệt độ dưới 0 °C là:", o: ["Đông lạnh", "Làm lạnh", "Làm khô", "Ướp muối"], x: "Đông lạnh giữ thực phẩm ở nhiệt độ dưới 0 °C, bảo quản được vài tuần đến vài tháng. Làm lạnh giữ ở nhiệt độ thấp nhưng trên 0 °C (ngăn mát tủ lạnh), chỉ bảo quản được ít ngày.", lv: 1 },
      { topic: "Bảo quản và chế biến thực phẩm", type: "mc", q: "Món ăn nào được chế biến không sử dụng nhiệt?", o: ["Dưa cải muối chua", "Cá rô phi rán giòn", "Rau muống luộc", "Thịt kho"], x: "Muối chua (dưa cải, cà muối) và trộn hỗn hợp (nộm, sa lát) là chế biến không sử dụng nhiệt. Rán, luộc, kho đều phải đun nấu.", lv: 2 },
      { topic: "Bảo quản và chế biến thực phẩm", type: "mc", q: "Luộc là cách làm chín thực phẩm:", o: ["Trong môi trường nhiều nước", "Trong chất béo", "Bằng sức nóng trực tiếp của lửa", "Bằng hơi nước"], x: "Luộc: làm chín trong nhiều nước. Rán: làm chín trong chất béo. Nướng: bằng sức nóng trực tiếp của lửa. Hấp: bằng hơi nước.", lv: 1 },
      { topic: "Bảo quản và chế biến thực phẩm", type: "tf", q: "Nên dùng chung một cái thớt để thái thịt sống và thức ăn đã nấu chín cho tiện.", a: false, x: "Dùng chung thớt dễ làm vi khuẩn từ thịt sống lây sang thức ăn chín. Cần dùng riêng thớt, dao cho thực phẩm sống và thực phẩm chín.", lv: 2 },
      { topic: "Bữa ăn kết nối yêu thương", type: "fill", q: "Nhóm của An đi chợ cho bữa ăn: 0,5 kg thịt giá 130 000 đồng/kg, 1 bó rau giá 10 000 đồng và 4 quả trứng giá 4 000 đồng/quả. Tổng số tiền phải trả là ___ đồng.", ans: ["91000", "91 000"], x: "Thịt: 0,5 × 130 000 = 65 000 (đồng). Trứng: 4 × 4 000 = 16 000 (đồng). Tổng: 65 000 + 10 000 + 16 000 = 91 000 (đồng).", lv: 3 }
    ]
  },

  /* Đề 2 (Phiên N6): cùng phạm vi, đủ 6 chủ đề của đề 1 (chữ chủ đề giữ nguyên), chia đúng theo ma trận của đề ngẫu nhiên:
     10 Biết, 8 Hiểu, 7 Vận dụng (đề 1 có 16 – 8 – 1, nên đề 2 có câu Vận dụng ở cả 6 bài: góc học tập, tiết kiệm điện, cảm biến
     báo rò rỉ gas, bữa sáng, các bước xào rau, tính tiền đi chợ và lượng thịt cần mua). Dạng câu theo khung Công văn 7991: nhiều
     lựa chọn, đúng/sai 4 ý, trả lời ngắn bằng số, nối cột (khu vực trong nhà – hoạt động, nhóm thực phẩm – chất dinh
     dưỡng chính), sắp xếp các bước bảo quản, chế biến. */
  "congnghe6-ck1-de2": {
    note: "Sách Kết nối tri thức, học kì I: Chương I Nhà ở (Bài 1 Khái quát về nhà ở, Bài 2 Xây dựng nhà ở, Bài 3 Ngôi nhà thông minh); Chương II Bảo quản và chế biến thực phẩm (Bài 4 Thực phẩm và dinh dưỡng, Bài 5 Phương pháp bảo quản và chế biến thực phẩm, Bài 6 Dự án Bữa ăn kết nối yêu thương). Trường nào học thêm Chương III Trang phục và thời trang trong học kì I thì cần ôn thêm phần đó. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Khái quát về nhà ở", type: "match", q: "Nối mỗi khu vực trong nhà ở với hoạt động chính diễn ra ở đó.", l: ["Phòng khách", "Phòng ngủ", "Nhà bếp", "Nhà tắm, nhà vệ sinh"], r: ["Sinh hoạt chung, tiếp khách", "Nghỉ ngơi", "Nấu ăn", "Tắm giặt, vệ sinh cá nhân", "Thờ cúng tổ tiên"], x: "Nhà ở thường chia thành các khu vực: sinh hoạt chung (phòng khách), nghỉ ngơi (phòng ngủ), nấu ăn (nhà bếp), vệ sinh (nhà tắm, nhà vệ sinh); nhiều nhà còn có khu vực thờ cúng.", lv: 1 },
      { topic: "Khái quát về nhà ở", type: "mc", q: "Ở nhà ở nông thôn truyền thống, khu vực nào thường được xây tách biệt với khu nhà chính?", o: ["Nhà bếp, nhà kho", "Phòng khách", "Gian thờ tổ tiên", "Chỗ ngủ của ông bà"], x: "Nhà ở nông thôn truyền thống thường xây nhà bếp, nhà kho tách biệt với khu nhà chính; khu nhà chính có ba gian hoặc năm gian.", lv: 1 },
      { topic: "Khái quát về nhà ở", type: "mc", q: "Vì sao ở các thành phố lớn có nhiều nhà chung cư cao tầng?", o: ["Vì đất chật, người đông, cần chỗ ở cho nhiều gia đình", "Vì nhà chung cư xây xong chỉ trong vài ngày", "Vì ở các thành phố lớn không bao giờ có mưa bão", "Vì nhà chung cư không cần dùng đến điện, nước"], x: "Ở thành phố lớn, đất chật mà người đông. Xây nhà nhiều tầng giúp trên một diện tích đất có chỗ ở cho nhiều gia đình.", lv: 2 },
      { topic: "Khái quát về nhà ở", type: "tf4", q: "Gia đình Hoa sắp xếp lại góc học tập cho Hoa. Mỗi cách làm sau đúng hay sai?", o: ["Đặt bàn học ở chỗ yên tĩnh, đủ ánh sáng.", "Đặt bàn học ngay cạnh bếp nấu ăn để tiện trông nồi.", "Xếp sách vở gọn gàng, sách hay dùng để ở tầm tay.", "Để quần áo bẩn trên bàn học cho tiện."], a: [true, false, true, false], x: "a), c) Đúng: góc học tập cần yên tĩnh, đủ sáng, gọn gàng để học tốt. b) Sai: cạnh bếp nóng, ồn, có khói và dễ nguy hiểm. d) Sai: để quần áo bẩn trên bàn học vừa mất vệ sinh, vừa bừa bộn.", lv: 3 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Trộn xi măng, cát và nước theo tỉ lệ thích hợp, ta được:", o: ["Vữa xây dựng", "Gạch nung", "Ngói lợp nhà", "Kính xây dựng"], x: "Xi măng trộn với cát và nước tạo thành vữa, dùng để xây gạch, trát tường. Trộn thêm đá, sỏi thì được bê tông.", lv: 1 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Gạch, ngói được làm từ nguyên liệu nào?", o: ["Đất sét", "Cát trắng", "Đá vôi", "Tre, nứa"], x: "Gạch, ngói được làm từ đất sét: tạo hình rồi nung trong lò ở nhiệt độ cao.", lv: 1 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Nhà anh Bảo có khung bằng bê tông cốt thép, còn sàn, cầu thang và cửa làm bằng gỗ. Kết hợp các vật liệu như vậy giúp ngôi nhà:", o: ["Vừa bền chắc, vừa đẹp", "Không cần làm móng", "Không bao giờ phải sửa chữa", "Không tốn chi phí xây dựng"], x: "Vật liệu tự nhiên và vật liệu nhân tạo được kết hợp với nhau để ngôi nhà vừa bền vững, vừa có tính thẩm mĩ.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Thiết bị nào sau đây thường được dùng trong ngôi nhà thông minh?", o: ["Ổ cắm điện bật, tắt được bằng điện thoại", "Quạt nan đan bằng tre để quạt tay", "Ổ khóa móc mở bằng chìa khóa sắt", "Đèn dầu thắp sáng bằng bấc và dầu hỏa"], x: "Ổ cắm thông minh kết nối mạng, cho phép bật, tắt đồ dùng điện bằng điện thoại, kể cả khi ở xa nhà.", lv: 1 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Loại bóng đèn nào sau đây giúp tiết kiệm điện nhất?", o: ["Bóng đèn LED", "Bóng đèn sợi đốt", "Bóng đèn halogen"], x: "Với cùng độ sáng, bóng đèn LED dùng ít điện hơn nhiều so với bóng đèn sợi đốt và bóng đèn halogen, lại bền hơn.", lv: 1 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Tối nào đến giờ ngủ, loa trong phòng của bé Na cũng tự đọc một câu chuyện ngắn rồi tự tắt. Đây là chức năng của hệ thống nào trong ngôi nhà thông minh?", o: ["Hệ thống giải trí", "Hệ thống chiếu sáng", "Hệ thống an ninh, an toàn", "Hệ thống kiểm soát nhiệt độ"], x: "Ti vi, loa, dàn âm thanh tự hoạt động theo cài đặt hoặc theo thói quen của người dùng thuộc hệ thống giải trí.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Bà của Minh ở nhà một mình và hay quên khóa bếp gas. Thiết bị nào của ngôi nhà thông minh giúp gia đình yên tâm hơn?", o: ["Cảm biến báo gas rò rỉ, gửi tin nhắn đến điện thoại", "Ti vi tự bật chương trình yêu thích của bà", "Đèn trang trí tự đổi màu theo tiếng nhạc", "Rèm cửa tự mở ra mỗi khi trời vừa sáng"], x: "Khi phát hiện gas rò rỉ, cảm biến kêu báo động và gửi tin nhắn đến điện thoại để người nhà kịp xử lí.", lv: 3 },
      { topic: "Ngôi nhà thông minh", type: "tf4", q: "Gia đình Nam muốn giảm tiền điện hằng tháng. Mỗi việc làm sau đúng hay sai?", o: ["Rút phích cắm sạc khi điện thoại đã đầy pin.", "Bật điều hòa ở 18 °C suốt cả ngày cho thật mát.", "Nấu cơm xong thì rút phích nồi cơm điện, không để chế độ hâm nóng cả ngày.", "Mở cửa sổ khi đang bật điều hòa cho thoáng."], a: [true, false, true, false], x: "a), c) Đúng: không để đồ dùng điện chạy khi không cần. b) Sai: để điều hòa quá lạnh và chạy suốt ngày rất tốn điện; nên đặt khoảng 26 – 28 °C. d) Sai: mở cửa sổ làm hơi lạnh thoát ra ngoài, điều hòa phải chạy nhiều hơn.", lv: 3 },
      { topic: "Thực phẩm và dinh dưỡng", type: "match", q: "Nối mỗi nhóm thực phẩm với chất dinh dưỡng chính mà nhóm đó cung cấp.", l: ["Gạo, ngô, khoai lang", "Thịt, cá, trứng", "Mỡ lợn, bơ, dầu ăn", "Cam, chanh, cà chua"], r: ["Chất tinh bột, chất đường", "Chất đạm", "Chất béo", "Vitamin"], x: "Gạo, ngô, khoai giàu chất tinh bột; thịt, cá, trứng giàu chất đạm; mỡ, bơ, dầu ăn giàu chất béo; cam, chanh, cà chua giàu vitamin (nhất là vitamin C).", lv: 1 },
      { topic: "Thực phẩm và dinh dưỡng", type: "mc", q: "Vì sao khi ăn nên tập trung, nhai kĩ, không vừa ăn vừa xem điện thoại?", o: ["Giúp tiêu hóa tốt, cảm nhận được vị ngon", "Để ăn thật nhanh cho xong bữa ăn", "Để không cần uống nước trong bữa ăn", "Để ăn được nhiều đồ ngọt hơn mọi ngày"], x: "Ăn chậm, nhai kĩ, tập trung vào bữa ăn giúp thức ăn được tiêu hóa tốt hơn và ta biết mình đã ăn đủ hay chưa.", lv: 2 },
      { topic: "Thực phẩm và dinh dưỡng", type: "mc", q: "Vì sao không nên ăn nhiều bánh kẹo, uống nhiều nước ngọt?", o: ["Dễ bị sâu răng, thừa cân, béo phì", "Làm cơ thể bị thiếu chất đường", "Làm cơ thể cao lên quá nhanh", "Làm mất vị ngon của bánh kẹo"], x: "Bánh kẹo, nước ngọt có nhiều đường. Ăn, uống nhiều dễ bị sâu răng, thừa cân, béo phì.", lv: 2 },
      { topic: "Thực phẩm và dinh dưỡng", type: "mc", q: "Bữa sáng của Nam thường chỉ có một gói mì ăn liền. Lời khuyên nào phù hợp nhất với Nam?", o: ["Ăn thêm trứng, sữa hoặc rau, quả cho đủ chất", "Ăn hai gói mì mỗi sáng cho no lâu hơn", "Chỉ uống một cốc nước ngọt thay bữa sáng", "Cho thật nhiều muối vào mì cho đậm đà"], x: "Một gói mì ăn liền chưa đủ chất cho bữa sáng. Thêm trứng, sữa, rau, quả giúp Nam có thêm nhiều chất bổ, đủ sức học cả buổi.", lv: 3 },
      { topic: "Bảo quản và chế biến thực phẩm", type: "mc", q: "Khi mua thực phẩm đóng gói như sữa hộp, bánh quy, điều quan trọng nhất cần xem trên bao bì là:", o: ["Hạn sử dụng", "Màu sắc của bao bì", "Kích thước của hộp", "Hình vẽ trang trí"], x: "Thực phẩm quá hạn sử dụng có thể đã bị hỏng, ăn vào dễ bị ngộ độc. Vì vậy cần xem hạn sử dụng trước khi mua.", lv: 1 },
      { topic: "Bảo quản và chế biến thực phẩm", type: "mc", q: "Kho là cách làm chín thực phẩm:", o: ["Trong lượng nước vừa phải, có vị mặn đậm đà", "Bằng hơi nước nóng", "Bằng cách trộn với rau sống, không đun nấu", "Bằng cách phơi khô dưới nắng"], x: "Kho là làm chín thực phẩm trong lượng nước vừa phải, nêm vị mặn đậm, như cá kho, thịt kho.", lv: 1 },
      { topic: "Bảo quản và chế biến thực phẩm", type: "mc", q: "Dấu hiệu nào cho biết miếng thịt đã bị hỏng, không nên ăn?", o: ["Có mùi hôi, mặt thịt nhớt, màu thâm xỉn", "Thịt có màu đỏ tươi, thớ thịt săn chắc", "Ấn tay vào thịt thấy đàn hồi, không lõm", "Mặt ngoài thịt khô ráo, không dính tay"], x: "Thịt tươi có màu đỏ tươi, săn chắc, ấn vào thấy đàn hồi. Thịt có mùi hôi, nhớt, thâm xỉn là đã hỏng, ăn vào dễ bị ngộ độc.", lv: 1 },
      { topic: "Bảo quản và chế biến thực phẩm", type: "order", q: "Sắp xếp các bước làm cá khô để bảo quản theo đúng thứ tự.", o: ["Làm sạch cá, bỏ ruột, rửa sạch", "Ướp cá với muối", "Phơi cá dưới nắng to trong nhiều ngày", "Cho cá đã khô vào túi kín, cất nơi khô ráo"], x: "Phải làm sạch cá trước, ướp muối cho ngấm rồi mới phơi. Cá khô cần cất trong túi kín, nơi khô ráo để không bị ẩm lại.", lv: 2 },
      { topic: "Bảo quản và chế biến thực phẩm", type: "tf4", q: "Mỗi ý sau về giữ vệ sinh, an toàn khi chế biến thực phẩm đúng hay sai?", o: ["Rửa tay sạch bằng xà phòng trước khi chế biến thực phẩm.", "Thực phẩm đã ôi thiu vẫn dùng được nếu nấu thật chín.", "Rau quả cần được ngâm, rửa kĩ dưới vòi nước sạch.", "Thịt, cá cần được nấu chín kĩ trước khi ăn."], a: [true, false, true, true], x: "a), c), d) Đúng: tay sạch, thực phẩm sạch và nấu chín kĩ giúp phòng ngộ độc thực phẩm. b) Sai: thực phẩm ôi thiu đã bị hỏng, có thể chứa chất độc mà nấu chín cũng không hết, phải bỏ đi.", lv: 2 },
      { topic: "Bảo quản và chế biến thực phẩm", type: "order", q: "Sắp xếp các bước làm món rau cải xào theo đúng thứ tự.", o: ["Nhặt, rửa sạch rau, để ráo rồi cắt khúc", "Phi thơm tỏi với một ít dầu ăn", "Cho rau vào, đảo nhanh tay trên lửa to", "Nêm gia vị vừa ăn, tắt bếp, cho ra đĩa"], x: "Rau phải được sơ chế (nhặt, rửa, cắt) trước. Phi thơm tỏi với dầu rồi mới cho rau vào xào nhanh trên lửa to; rau chín thì nêm gia vị, tắt bếp.", lv: 3 },
      { topic: "Bữa ăn kết nối yêu thương", type: "mc", q: "Vì sao trước khi đi chợ cho bữa ăn, cần tính toán chi phí và ghi danh sách thực phẩm cần mua?", o: ["Để mua đủ thứ cần mà không vượt số tiền dự định", "Để mua được thật nhiều thực phẩm đắt tiền", "Để cả nhà không cần phải nấu ăn ở nhà nữa", "Để người bán hàng tính tiền được nhanh hơn"], x: "Tính trước chi phí và ghi danh sách giúp mua đủ, không quên, không mua thừa và không vượt quá số tiền gia đình dự định.", lv: 2 },
      { topic: "Bữa ăn kết nối yêu thương", type: "num", q: "Mẹ đưa An 100 000 đồng đi chợ. An mua 0,2 kg thịt bò giá 250 000 đồng/kg, 2 bó rau cải giá 6 000 đồng/bó và 1 kg khoai tây giá 20 000 đồng/kg. An còn lại bao nhiêu tiền?", ans: 18000, unit: "đồng", x: "Thịt bò: 0,2 × 250 000 = 50 000 (đồng). Rau cải: 2 × 6 000 = 12 000 (đồng). Khoai tây: 20 000 đồng. Tổng: 50 000 + 12 000 + 20 000 = 82 000 (đồng). Còn lại: 100 000 − 82 000 = 18 000 (đồng).", lv: 3 },
      { topic: "Bữa ăn kết nối yêu thương", type: "num", q: "Nhóm của Hà nấu món thịt kho cho 6 người. Mỗi người cần khoảng 0,15 kg thịt. Nhóm cần mua bao nhiêu ki-lô-gam thịt?", ans: 0.9, unit: "kg", x: "Số thịt cần mua: 0,15 × 6 = 0,9 (kg).", lv: 3 }
    ]
  },

  /* ---------- Công nghệ 6 · Kiểm tra giữa học kì I (Kết nối tri thức) ----------
     Phạm vi nửa đầu học kì I (Bài 1–3), ghi ở note. Câu tự soạn. Mức độ lv của đề 1 ghi ở Phiên N25. Phiên DS7 dò với sách in
     năm 2026: chủ đề theo tên ba bài, câu ngoài sách (chất đốt, gas, than, biogas, an toàn ở công trường) soạn lại, giữ mức và
     dạng câu (cách xếp mức như đề cuối kì I ở đầu file: nêu vai trò, bộ phận, vật liệu, nguồn năng lượng, thiết bị là Biết; phân loại, giải
     thích, nhận ra chức năng của hệ thống trong tình huống là Hiểu; xử lí tình huống, chọn cách làm, tính toán là Vận dụng).
     Hai đề là kho của đề ngẫu nhiên "congnghe6-gk1-ngau-nhien" (ma trận ở data/banks/index.js). */
  "congnghe6-gk1-de1": {
    note: "Sách Kết nối tri thức, Chương I Nhà ở: Bài 1 Khái quát về nhà ở, Bài 2 Xây dựng nhà ở, Bài 3 Ngôi nhà thông minh. Trường nào kiểm tra cả Bài 4 Thực phẩm và dinh dưỡng thì ôn thêm phần đó ở đề cuối kì I. Có lời giải từng câu.",
    questions: [
      { topic: "Khái quát về nhà ở", type: "mc", q: "Điều nào sau đây KHÔNG phải là vai trò của nhà ở?", o: ["Là nơi sản xuất của nhà máy, xí nghiệp", "Bảo vệ con người trước mưa, nắng, gió, bão", "Là nơi các thành viên trong gia đình ăn uống, ngủ nghỉ", "Là nơi cả gia đình quây quần, gắn bó với nhau"], x: "Nhà ở là nơi ở, bảo vệ con người trước những tác động xấu của thiên nhiên và xã hội, đáp ứng nhu cầu sinh hoạt hằng ngày và gắn kết các thành viên trong gia đình. Nhà máy, xí nghiệp là nơi sản xuất, không phải nhà ở.", lv: 1 },
      { topic: "Khái quát về nhà ở", type: "fill", q: "Bộ phận bao quanh ngôi nhà, ngăn không gian bên trong với bên ngoài và chia bên trong thành các phòng là ___ nhà.", ans: ["tường"], x: "Tường nhà bao che ngôi nhà, ngăn không gian bên trong với bên ngoài và chia bên trong thành các phòng.", lv: 1 },
      { topic: "Khái quát về nhà ở", type: "mc", q: "Bộ phận nào của ngôi nhà che mưa, che nắng, bảo vệ các bộ phận bên dưới?", o: ["Mái nhà", "Móng nhà", "Sàn nhà", "Cửa sổ"], x: "Mái nhà ở trên cùng, che mưa, che nắng cho các bộ phận bên dưới và cho người ở trong nhà.", lv: 1 },
      { topic: "Khái quát về nhà ở", type: "mc", q: "Nơi cả gia đình quây quần trò chuyện, tiếp khách thuộc khu vực nào trong nhà?", o: ["Khu vực sinh hoạt chung", "Khu vực nghỉ ngơi", "Khu vực nấu ăn", "Khu vực vệ sinh"], x: "Phòng khách là khu vực sinh hoạt chung: nơi cả nhà trò chuyện, xem ti vi, tiếp khách. Khu vực nghỉ ngơi là phòng ngủ.", lv: 2 },
      { topic: "Khái quát về nhà ở", type: "mc", q: "Kiểu nhà nào thường gặp ở các thành phố lớn?", o: ["Nhà chung cư", "Nhà sàn", "Nhà nổi", "Nhà ba gian truyền thống"], x: "Ở thành phố, đất chật người đông nên có nhiều nhà chung cư và nhà mặt phố nhiều tầng. Nhà sàn, nhà nổi là nhà ở các khu vực đặc thù; nhà ba gian là nhà ở nông thôn truyền thống.", lv: 1 },
      { topic: "Khái quát về nhà ở", type: "mc", q: "Nhà nổi thường có ở khu vực nào của nước ta?", o: ["Vùng sông nước như miền Tây Nam Bộ", "Vùng núi cao phía Bắc", "Trung tâm các thành phố lớn", "Vùng đồi núi khô hạn"], x: "Nhà nổi có hệ thống phao dưới sàn nên nổi được trên mặt nước, thường gặp ở vùng sông nước như Đồng bằng sông Cửu Long.", lv: 1 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Vật liệu nào dưới đây là vật liệu nhân tạo?", o: ["Kính", "Cát", "Đá", "Tre"], x: "Kính do con người sản xuất nên là vật liệu nhân tạo (như thép, thạch cao). Cát, đá, tre là vật liệu có sẵn trong tự nhiên.", lv: 2 },
      { topic: "Xây dựng nhà ở", type: "tf", q: "Gạch, ngói được làm từ đất sét nên là vật liệu có sẵn trong tự nhiên.", a: false, x: "Sai. Đất sét có sẵn trong tự nhiên, còn gạch, ngói do con người nung đất sét tạo ra nên là vật liệu nhân tạo.", lv: 2 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Thợ đang sơn lại các phòng đã trát phẳng và lát gạch men cho nền nhà. Ngôi nhà đang ở bước nào của quá trình xây dựng?", o: ["Hoàn thiện", "Thiết kế", "Thi công thô"], x: "Xây dựng nhà ở gồm ba bước chính: thiết kế → thi công thô → hoàn thiện. Trát, sơn, lát nền là việc của bước hoàn thiện.", lv: 2 },
      { topic: "Xây dựng nhà ở", type: "tf", q: "Thợ đang làm hệ thống đường ống nước và đường dây điện đi ngầm cho ngôi nhà mới của bác Tư. Đây là công việc của bước hoàn thiện.", a: false, x: "Sai. Làm hệ thống đường ống nước, đường điện là việc của bước thi công thô.", lv: 3 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Để đổ bê tông làm sàn nhà, thợ trộn đá nhỏ với cát, nước và vật liệu nào sau đây?", o: ["Xi măng", "Thạch cao", "Mùn cưa", "Đất sét"], x: "Đá nhỏ trộn với cát, xi măng và nước tạo thành bê tông. Thạch cao, mùn cưa, đất sét không dùng để trộn bê tông.", lv: 1 },
      { topic: "Xây dựng nhà ở", type: "tf", q: "Làm móng nhà, dựng khung và làm mái là những công việc của bước thi công thô.", a: true, x: "Đúng. Thi công thô là bước hình thành khung cho ngôi nhà, gồm làm móng, dựng khung, làm mái và một số việc khác.", lv: 1 },
      { topic: "Xây dựng nhà ở", type: "tf", q: "Khi sửa lại nhà, gia đình Thảo tận dụng gạch, gỗ cũ còn tốt thay vì mua mới toàn bộ. Cách làm này vừa đỡ tốn tiền, vừa giảm ảnh hưởng xấu đến môi trường.", a: true, x: "Đúng. Dùng lại vật liệu còn tốt giúp bớt tiền mua vật liệu mới. Sản xuất vật liệu mới tốn năng lượng, có loại (như xi măng) còn thải ra nhiều khí carbonic, ảnh hưởng xấu tới môi trường.", lv: 3 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Ngôi nhà nào dưới đây là ngôi nhà thông minh?", o: ["Nhà có đèn, rèm cửa, điều hòa tự hoạt động hoặc điều khiển được từ xa qua điện thoại", "Nhà có nhiều tầng và nhiều phòng rộng", "Nhà xây bằng gạch, ngói, xi măng", "Nhà có vườn cây và ao cá"], x: "Ngôi nhà thông minh được lắp hệ thống điều khiển tự động hoặc bán tự động cho các đồ dùng trong nhà. Nhà to, nhiều phòng hay xây bằng gạch chưa phải là nhà thông minh.", lv: 1 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Đang ở cơ quan, bố mở điện thoại xem camera trong nhà và nhận được tin báo khi có người lạ vào cổng. Đây là chức năng của hệ thống nào?", o: ["Hệ thống an ninh, an toàn", "Hệ thống chiếu sáng", "Hệ thống giải trí", "Hệ thống kiểm soát nhiệt độ"], x: "Camera, báo động khi có người lạ, báo cháy… thuộc hệ thống an ninh, an toàn của ngôi nhà thông minh.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Điều hòa tự bật khi phòng nóng và tự điều chỉnh để phòng luôn mát vừa phải. Đây là chức năng của hệ thống nào?", o: ["Hệ thống kiểm soát nhiệt độ", "Hệ thống chiếu sáng", "Hệ thống giải trí", "Hệ thống an ninh, an toàn"], x: "Hệ thống kiểm soát nhiệt độ tự điều chỉnh điều hòa, quạt… để nhiệt độ trong phòng luôn dễ chịu.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Chủ nhà nói “Mở nhạc”, loa trong phòng khách tự phát bài hát yêu thích. Đây là chức năng của hệ thống nào?", o: ["Hệ thống giải trí", "Hệ thống an ninh, an toàn", "Hệ thống chiếu sáng", "Hệ thống kiểm soát nhiệt độ"], x: "Ti vi, loa, dàn âm thanh được điều khiển bằng giọng nói hoặc điện thoại thuộc hệ thống giải trí.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Cả nhà đã đi chơi xa mới nhớ ra quên tắt đèn. Nếu ở trong ngôi nhà thông minh, gia đình có thể:", o: ["Dùng điện thoại để tắt đèn từ xa", "Phải quay về nhà để tắt đèn", "Nhờ thợ điện phá khóa vào nhà", "Gọi điện cho công ty điện lực cắt điện cả khu phố"], x: "Ngôi nhà thông minh cho phép điều khiển đồ dùng từ xa qua điện thoại hoặc máy tính bảng. Đây là đặc điểm tiện ích của ngôi nhà thông minh.", lv: 3 },
      { topic: "Ngôi nhà thông minh", type: "tf", q: "Ngôi nhà thông minh giúp tiết kiệm năng lượng, ví dụ đèn tự tắt khi không còn ai trong phòng.", a: true, x: "Đúng. Tiết kiệm năng lượng là một đặc điểm của ngôi nhà thông minh, cùng với tiện ích và an ninh, an toàn.", lv: 1 },
      { topic: "Ngôi nhà thông minh", type: "tf", q: "Ngôi nhà thông minh nhất thiết phải là ngôi nhà rất to và đắt tiền.", a: false, x: "Sai. Nhà nhỏ vẫn có thể là nhà thông minh nếu có các đồ dùng tự động hoặc điều khiển được từ xa. Điều làm nên ngôi nhà thông minh là hệ thống điều khiển, không phải kích thước hay giá tiền.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Vì sao cần sử dụng tiết kiệm năng lượng trong gia đình?", o: ["Giảm chi phí cho gia đình, bảo vệ tài nguyên và môi trường", "Để đồ dùng điện trong nhà chạy nhanh hơn", "Để không bao giờ phải dùng đến điện", "Để nhà lúc nào cũng tối và mát"], x: "Dùng năng lượng tiết kiệm và hiệu quả giúp gia đình bớt chi phí (tiền điện, tiền gas…), giữ gìn tài nguyên thiên nhiên và góp phần bảo vệ môi trường.", lv: 1 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Bình nước nóng đặt trên mái nhà, dùng ánh nắng để làm nóng nước. Bình này sử dụng nguồn năng lượng nào?", o: ["Năng lượng mặt trời", "Năng lượng điện lưới", "Năng lượng chất đốt", "Năng lượng của dòng nước"], x: "Bình nước nóng năng lượng mặt trời dùng ánh nắng làm nóng nước, giúp gia đình bớt tiền điện.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Việc làm nào dưới đây gây lãng phí điện?", o: ["Bật điều hòa nhưng vẫn mở cửa sổ", "Tắt ti vi khi không xem", "Học bài ở chỗ có ánh sáng tự nhiên vào ban ngày", "Rút sạc khi điện thoại đã đầy pin"], x: "Mở cửa sổ khi bật điều hòa làm hơi lạnh thoát ra ngoài, máy phải chạy nhiều hơn nên tốn điện. Ba việc còn lại đều giúp tiết kiệm điện.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Khi mua đồ dùng điện mới, để tiết kiệm điện nên chọn loại:", o: ["Có dán nhãn tiết kiệm năng lượng", "Có công suất lớn nhất cửa hàng", "Có màu sắc sặc sỡ nhất", "Có kích thước to nhất"], x: "Đồ dùng có dán nhãn tiết kiệm năng lượng dùng ít điện hơn mà vẫn làm việc tốt. Đồ dùng công suất lớn thường tốn nhiều điện hơn.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "fill", q: "Gia đình anh Tâm ở ven biển lắp một máy phát điện nhỏ có cánh quạt quay nhờ năng lượng ___, một nguồn năng lượng thân thiện với môi trường.", ans: ["gió"], x: "Gió làm quay cánh quạt của máy phát điện. Năng lượng gió có sẵn trong tự nhiên, thân thiện với môi trường.", lv: 1 }
    ]
  },
  /* Đề 2 (Phiên N25): cùng phạm vi Bài 1–3, đủ 3 chủ đề của đề 1 (chữ chủ đề giữ nguyên), chia đúng theo ma trận của đề ngẫu
     nhiên: 10 Biết, 8 Hiểu, 7 Vận dụng (đề 1 có 11 – 11 – 3, nên đề 2 có nhiều câu Vận dụng: sắp xếp khu vực trong nhà, nhà ở vùng
     ngập, chọn vật liệu theo điều kiện, giảm tiền điện, tính tiền điện tiết kiệm, đèn cho người già, chọn thiết bị thông minh). Dạng
     câu theo khung Công văn 7991: nhiều lựa chọn, đúng/sai 4 ý, trả lời ngắn bằng số. Hai đề là kho của đề ngẫu nhiên
     "congnghe6-gk1-ngau-nhien" (không có câu riêng); ô Biết của mỗi chủ đề rút 3–4 câu nên câu nào của đề 1 cũng có thể
     được rút cùng câu của đề 2: đề 2 không hỏi lại điều mà đề bài, lựa chọn hay lời giải của đề 1 đã nêu (các phần của nhà, kiểu
     nhà theo vùng, ba bước xây nhà, vật liệu tự nhiên và nhân tạo, bốn hệ thống và ba đặc điểm của ngôi nhà thông minh). */
  "congnghe6-gk1-de2": {
    note: "Sách Kết nối tri thức, Chương I Nhà ở: Bài 1 Khái quát về nhà ở, Bài 2 Xây dựng nhà ở, Bài 3 Ngôi nhà thông minh. Trường nào kiểm tra cả Bài 4 Thực phẩm và dinh dưỡng thì ôn thêm phần đó ở đề cuối kì I. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Khái quát về nhà ở", type: "mc", q: "Bộ phận nào của ngôi nhà có tác dụng lấy ánh sáng và không khí vào trong nhà?", o: ["Cửa sổ", "Móng nhà", "Sàn nhà", "Cột nhà"], x: "Cửa sổ, cửa đi giúp lấy ánh sáng, thông gió cho ngôi nhà. Móng, sàn, cột là các bộ phận chịu lực.", lv: 1 },
      { topic: "Khái quát về nhà ở", type: "mc", q: "Nhà chung cư là kiểu nhà:", o: ["Có nhiều tầng, nhiều gia đình ở trong cùng một tòa nhà", "Chỉ có một tầng và một gia đình ở", "Dựng trên các cột cao, sàn cách mặt đất", "Làm trên mặt nước, có thể di chuyển được"], x: "Nhà chung cư được xây để phục vụ nhiều gia đình: mỗi gia đình có không gian riêng, cùng dùng chung khu để xe, khu mua bán, khu sinh hoạt cộng đồng…", lv: 1 },
      { topic: "Khái quát về nhà ở", type: "mc", q: "Trong nhà ở, “gian nhà” là gì?", o: ["Phần không gian trong nhà được giới hạn bởi các hàng cột hoặc vách ngăn", "Một tầng của ngôi nhà nhiều tầng", "Phần sân ở phía trước cửa ra vào", "Một căn nhà nhỏ dựng ở góc vườn"], x: "Gian nhà là phần không gian trong nhà nằm giữa các hàng cột hoặc vách ngăn. Nhà ở nông thôn truyền thống thường có khu nhà chính ba gian hoặc năm gian.", lv: 1 },
      { topic: "Khái quát về nhà ở", type: "mc", q: "Vì sao nhà sàn ở vùng núi thường được dựng cao cách mặt đất?", o: ["Để hợp với địa hình đồi núi và tập quán sinh hoạt của người dân nơi đó", "Để ngôi nhà trông cao và đẹp hơn", "Vì ở vùng núi không có xi măng để xây nhà", "Để tiết kiệm gỗ làm nhà"], x: "Nhà sàn dựng trên các cột, phù hợp với địa hình và tập quán sinh hoạt của người dân. Phần sàn để ở, sinh hoạt, nấu ăn; ở vùng cao, phần dưới sàn thường dùng để cất giữ công cụ lao động.", lv: 2 },
      { topic: "Khái quát về nhà ở", type: "tf4", q: "Mỗi ý sau về nhà ở đúng hay sai?", o: ["Mỗi khu vực trong nhà nên được bố trí phù hợp với hoạt động diễn ra ở đó.", "Nhà ở chỉ cần đẹp, không cần thoáng mát và sạch sẽ.", "Nhà mặt phố thường được thiết kế để vừa ở vừa có thể kinh doanh.", "Nhà ở nông thôn và nhà ở thành thị có thể khác nhau về kiểu dáng."], a: [true, false, true, true], x: "a), c), d) Đúng. b) Sai: nhà ở cần thoáng mát, sạch sẽ, đủ ánh sáng để bảo vệ sức khỏe người ở; đẹp chỉ là một yêu cầu thêm.", lv: 2 },
      { topic: "Khái quát về nhà ở", type: "tf4", q: "Gia đình Lan sắp xếp các khu vực trong ngôi nhà nhỏ của mình. Mỗi cách làm sau có hợp lí không?", o: ["Đặt bếp nấu ăn ở chỗ thoáng khí để khói, mùi dễ thoát ra ngoài.", "Kê giường ngủ ngay cạnh bếp đang nấu cho ấm.", "Dành một góc yên tĩnh, đủ ánh sáng làm góc học tập.", "Để xe máy trong phòng ngủ cho an toàn."], a: [true, false, true, false], x: "a), c) Hợp lí. b) Không: khói, mùi và nhiệt từ bếp ảnh hưởng đến giấc ngủ, dễ gây cháy. d) Không: xe máy có xăng, khói, nên để ở khu vực riêng.", lv: 3 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Vật liệu nào sau đây thường được dùng để lợp mái nhà?", o: ["Ngói", "Xi măng", "Cát", "Kính"], x: "Ngói (cũng như tôn, lá cọ…) dùng để lợp mái nhà. Xi măng, cát không dùng để lợp mái; kính thường dùng làm cửa.", lv: 1 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Trong xây dựng nhà ở, thép thường được dùng để:", o: ["Làm khung, cột, dầm chịu lực", "Lợp mái", "Làm lớp vữa trát", "Lát nền"], x: "Thép cứng, chịu lực tốt nên dùng làm khung, cột, dầm (thường kết hợp với bê tông thành bê tông cốt thép).", lv: 1 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Khung mái, cầu thang, tủ và bàn ghế trong ngôi nhà truyền thống thường được làm từ vật liệu nào sau đây?", o: ["Gỗ", "Cát", "Xi măng", "Kính"], x: "Gỗ dễ gia công, dùng làm khung nhà, mái nhà, sàn nhà, giá đỡ và đồ nội thất như tủ, bàn ghế.", lv: 1 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Khi xây nhà, vì sao phải vẽ bản thiết kế và dự tính chi phí trước?", o: ["Để biết trước hình dáng ngôi nhà và số tiền cần có", "Để ngôi nhà xây xong trông to hơn", "Để không cần thuê thợ xây", "Để không phải mua vật liệu xây dựng"], x: "Thiết kế giúp chủ nhà hình dung được ngôi nhà sau khi xây, bảo đảm ngôi nhà vững chắc và cho biết cần chuẩn bị bao nhiêu vật liệu, kinh phí.", lv: 2 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Khi dựng khung cho ngôi nhà, thợ làm lệch, không vuông vắn nhưng vẫn làm tiếp các việc sau. Điều gì dễ xảy ra?", o: ["Các việc làm sau gặp khó khăn, tốn thêm tiền sửa chữa", "Ngôi nhà sẽ xây xong nhanh hơn", "Không ảnh hưởng gì đến ngôi nhà", "Ngôi nhà sẽ vững chắc hơn"], x: "Phần khung là nền tảng của ngôi nhà. Làm tốt từ đầu thì các bước sau thuận lợi, tiết kiệm chi phí; làm sai thì phải sửa lại, tốn thời gian và tiền.", lv: 2 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Nhà của Minh ở vùng thường bị ngập nước vào mùa mưa. Khi xây nhà, gia đình Minh nên:", o: ["Tôn nền nhà cao hơn mức nước ngập thường gặp", "Xây nhà thấp hơn mặt đường cho mát", "Dùng toàn bộ gỗ để làm móng", "Không cần làm móng"], x: "Nền nhà cao hơn mức ngập giúp nhà khô ráo, đồ đạc không bị hỏng. Móng cần chắc chắn, không làm bằng gỗ (dễ mục khi ngập).", lv: 3 },
      { topic: "Xây dựng nhà ở", type: "mc", q: "Gia đình bác Nam ở nông thôn, quanh vùng có nhiều gỗ và tre, kinh tế chưa dư dả. Khi làm nhà, bác nên chọn vật liệu nào là hợp lí?", o: ["Tận dụng gỗ, tre sẵn có ở địa phương", "Nhập thép và kính loại đắt tiền từ nước ngoài", "Chỉ dùng đá hoa cương cho sang trọng", "Dùng toàn bộ vật liệu bằng nhựa"], x: "Chọn vật liệu phù hợp với điều kiện kinh tế và sẵn có ở địa phương giúp giảm chi phí vận chuyển và mua sắm. Gỗ, tre bền, dễ gia công, hợp với nhà ở nông thôn.", lv: 3 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Thiết bị nào sau đây thường có trong ngôi nhà thông minh để nhận biết có người đi vào phòng?", o: ["Cảm biến chuyển động", "Bàn là", "Ấm đun nước", "Chổi quét nhà"], x: "Cảm biến chuyển động phát hiện người đi vào phòng để bật đèn, báo động… Bàn là, ấm đun nước, chổi là đồ dùng thường.", lv: 1 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Trong ngôi nhà thông minh, các thiết bị được kết nối với bộ điều khiển và với nhau qua:", o: ["Mạng Internet hoặc mạng không dây trong nhà", "Dây thừng", "Ống nước", "Thư gửi qua bưu điện"], x: "Các thiết bị thông minh kết nối với nhau và với điện thoại qua mạng không dây (wifi) hoặc Internet, nhờ đó điều khiển được từ xa.", lv: 1 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Rô-bốt hút bụi tự chạy khắp nhà và tự về sạc pin khi hết điện. Thiết bị này giúp ích gì cho gia đình?", o: ["Đỡ vất vả khi dọn dẹp nhà cửa", "Làm cho ngôi nhà rộng hơn", "Giúp gia đình không phải dùng điện", "Thay cho camera trông nhà"], x: "Rô-bốt hút bụi tự làm việc nhà, giúp con người đỡ vất vả. Rô-bốt vẫn dùng điện (tự về sạc pin) và không trông nhà như camera.", lv: 1 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Sử dụng năng lượng tiết kiệm và hiệu quả trong gia đình được hiểu là:", o: ["Dùng năng lượng đúng lúc, đúng chỗ, dùng ít mà vẫn đủ cho nhu cầu", "Không dùng điện, gas trong nhà nữa", "Chỉ dùng điện vào ban đêm", "Dùng bao nhiêu cũng được miễn là trả đủ tiền"], x: "Sử dụng năng lượng tiết kiệm và hiệu quả là dùng đúng lúc, đúng chỗ, dùng ít năng lượng mà vẫn bảo đảm được nhu cầu.", lv: 1 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Đúng 6 giờ sáng, rèm cửa phòng ngủ tự kéo ra cho ánh nắng chiếu vào phòng. Đây là chức năng của hệ thống nào trong ngôi nhà thông minh?", o: ["Hệ thống chiếu sáng", "Hệ thống giải trí", "Hệ thống kiểm soát nhiệt độ", "Hệ thống an ninh, an toàn"], x: "Hệ thống chiếu sáng điều khiển đèn và rèm cửa để trong nhà đủ sáng khi cần.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "tf4", q: "Mỗi ý sau về ngôi nhà thông minh đúng hay sai?", o: ["Ngôi nhà thông minh có thể giúp người già, người khuyết tật sinh hoạt dễ dàng hơn.", "Mọi ngôi nhà có ti vi và tủ lạnh đều là ngôi nhà thông minh.", "Cửa cổng có thể tự mở khi nhận ra xe của chủ nhà đang về.", "Ngôi nhà thông minh không cần điện vẫn hoạt động bình thường."], a: [true, false, true, false], x: "a), c) Đúng. b) Sai: có ti vi, tủ lạnh chưa phải nhà thông minh; phải có hệ thống điều khiển tự động hoặc từ xa. d) Sai: các thiết bị thông minh đều cần điện để hoạt động.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Mùa hè, vì sao nên đặt điều hòa ở khoảng 26–28 °C thay vì 18 °C?", o: ["Vừa đủ mát mà tốn ít điện hơn", "Vì điều hòa không hạ được xuống 18 °C", "Để trong phòng nóng hơn ngoài trời", "Vì nhiệt độ thấp làm máy chạy nhanh hơn"], x: "Đặt nhiệt độ quá thấp, máy phải chạy nhiều hơn nên tốn điện và dễ gây cảm lạnh. 26–28 °C đủ mát, tiết kiệm điện và tốt cho sức khỏe.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "tf4", q: "Mỗi ý sau về sử dụng năng lượng trong gia đình đúng hay sai?", o: ["Đun nước bằng ấm có nắp đậy sẽ sôi nhanh hơn, đỡ tốn điện, gas.", "Mở tủ lạnh thật lâu để chọn đồ ăn không làm tốn điện.", "Tắt máy tính khi không dùng trong thời gian dài giúp tiết kiệm điện.", "Bật bình nóng lạnh suốt cả ngày cho tiện là cách dùng hợp lí."], a: [true, false, true, false], x: "a), c) Đúng. b) Sai: mở tủ lạnh lâu làm hơi lạnh thoát ra, máy phải chạy nhiều hơn. d) Sai: chỉ bật bình nóng lạnh trước khi tắm 15–20 phút rồi tắt.", lv: 2 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Ông của Mai ở nhà một mình, mắt kém và hay đi lại ban đêm. Trang bị nào của ngôi nhà thông minh giúp ông an toàn hơn?", o: ["Đèn hành lang tự bật khi có người đi qua", "Loa phát nhạc to suốt đêm", "Rèm cửa tự đóng khi trời tối", "Ti vi tự mở kênh thời sự mỗi sáng"], x: "Đèn tự bật khi có người giúp ông nhìn rõ đường đi ban đêm, tránh vấp ngã. Loa, rèm, ti vi không giúp đi lại an toàn.", lv: 3 },
      { topic: "Ngôi nhà thông minh", type: "tf4", q: "Gia đình Bình muốn lắp một số thiết bị thông minh với số tiền có hạn. Mỗi lựa chọn sau có hợp lí không?", o: ["Ưu tiên lắp cảm biến khói và khóa cửa thông minh để bảo đảm an toàn.", "Mua thật nhiều loa thông minh cho mọi phòng trước tiên.", "Chọn các thiết bị có thể điều khiển chung bằng một ứng dụng trên điện thoại.", "Lắp đèn tự tắt khi không có người ở các phòng ít dùng để tiết kiệm điện."], a: [true, false, true, true], x: "a), c), d) Hợp lí: ưu tiên an toàn, tiện điều khiển và tiết kiệm năng lượng. b) Không: loa giải trí không cần thiết bằng các thiết bị an toàn, lại tốn tiền.", lv: 3 },
      { topic: "Ngôi nhà thông minh", type: "mc", q: "Trong một ngày nắng to, gia đình An muốn giảm tiền điện. Việc làm nào hợp lí nhất?", o: ["Phơi quần áo ngoài nắng thay cho máy sấy, mở cửa cho thoáng thay cho bật điều hòa", "Bật tất cả đèn trong nhà cho sáng", "Đóng kín cửa, bật điều hòa và đèn cả ngày", "Dùng máy sấy quần áo cả buổi chiều"], x: "Tận dụng ánh nắng và không khí tự nhiên thay cho máy sấy, điều hòa giúp tiết kiệm điện. Bật đèn, điều hòa khi không cần đều lãng phí điện.", lv: 3 },
      { topic: "Ngôi nhà thông minh", type: "num", q: "Tháng trước nhà Lan dùng hết 180 số điện. Tháng này, cả nhà thay toàn bộ bóng đèn cũ bằng bóng đèn LED nên chỉ dùng 150 số. Nếu tính trung bình 2 500 đồng một số điện, tháng này nhà Lan tiết kiệm được bao nhiêu tiền điện?", ans: 75000, unit: "đồng", x: "Số điện tiết kiệm: 180 − 150 = 30 (số). Số tiền tiết kiệm: 30 × 2 500 = 75 000 (đồng).", lv: 3 }
    ]
  },
  /* ---------- Công nghệ 6 · Kiểm tra giữa học kì II (Kết nối tri thức) ----------
     Phạm vi nửa đầu học kì II ghi ở note (Chương III Trang phục và thời trang: Bài 7–9; Chương IV Đồ dùng điện trong gia đình:
     Bài 10). Câu tự soạn, mức độ lv ở từng câu (Phiên N12b). Hai đề là kho của đề ngẫu nhiên "congnghe6-gk2-ngau-nhien" (không
     có câu riêng nên không ghi vào file này; ma trận ở data/banks/index.js); hai đề cùng phân bố chủ đề và mức như ma trận, nên ô
     nào cũng có gấp đôi số câu ô đó rút. Cách xếp mức: nêu khái niệm, nguồn gốc các loại vải, các công việc bảo quản, kí hiệu trên
     nhãn, đơn vị, định nghĩa thông số là Biết; giải thích vì sao, nhận ra phong cách, cảm giác do màu sắc, kiểu may tạo ra, nhận
     xét một ý là Hiểu; chọn trang phục, chọn vải, chọn đồ dùng điện cho một tình huống, sắp xếp các bước làm là Vận dụng. Câu ở
     hai ô khác nhau, cả hai câu của một ô, có thể cùng được rút vào một đề, nên đề bài, các lựa chọn, lời giải không ghi sẵn đáp
     án của câu khác: mỗi phong cách thời trang chỉ được nhận ra ở một câu trong cả kho, mỗi kí hiệu bảo quản chỉ hỏi ở một câu. */
  "congnghe6-gk2-de1": {
    note: "Sách Kết nối tri thức, nửa đầu học kì II: Chương III Trang phục và thời trang (Bài 7 Trang phục trong đời sống, Bài 8 Sử dụng và bảo quản trang phục, Bài 9 Thời trang); Chương IV Đồ dùng điện trong gia đình (Bài 10 Khái quát về đồ dùng điện trong gia đình). Có trường học Bài 7 từ cuối học kì I, có trường chỉ kiểm tra đến Bài 9; phụ huynh đối chiếu với đề cương của trường. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Trang phục trong đời sống", type: "mc", q: "Trang phục gồm:", o: ["Quần áo và một số vật dụng đi kèm như mũ, giày, khăn, thắt lưng", "Chỉ có quần và áo", "Chỉ có giày, dép và mũ", "Các loại vải chưa may"], x: "Trang phục là các loại quần áo và một số vật dụng đi kèm (mũ, giày, dép, khăn, thắt lưng, túi xách…), trong đó quần áo là vật dụng quan trọng nhất.", lv: 1 },
      { topic: "Trang phục trong đời sống", type: "mc", q: "Vải sợi thiên nhiên được dệt từ:", o: ["Sợi bông, sợi tơ tằm, sợi lông cừu", "Sợi nhựa tái chế", "Sợi ni-lông, sợi pô-li-ét-te", "Sợi kim loại"], x: "Vải sợi thiên nhiên có nguồn gốc từ thực vật (sợi bông, sợi lanh, sợi đay) và động vật (tơ tằm, lông cừu). Ni-lông, pô-li-ét-te là sợi tổng hợp.", lv: 1 },
      { topic: "Trang phục trong đời sống", type: "mc", q: "Vai trò của trang phục đối với con người là:", o: ["Bảo vệ cơ thể và góp phần làm đẹp cho con người", "Chỉ để che nắng", "Chỉ để thể hiện sự giàu có", "Thay thế cho nhà ở"], x: "Trang phục che chở, bảo vệ cơ thể khỏi tác hại của thời tiết, môi trường và góp phần tôn lên vẻ đẹp của người mặc.", lv: 1 },
      { topic: "Trang phục trong đời sống", type: "tf4", q: "Mỗi ý sau về các loại vải may trang phục đúng hay sai?", o: ["Vải sợi thiên nhiên có nguồn gốc từ thực vật và động vật.", "Vải sợi tổng hợp thấm mồ hôi tốt hơn vải bông.", "Len là vải dệt từ lông cừu, giữ ấm tốt.", "Vải sợi tổng hợp bền, ít nhàu."], a: [true, false, true, true], x: "a), c), d) Đúng: sợi thiên nhiên lấy từ cây và từ động vật; len ấm; vải tổng hợp bền, ít nhàu. b) Sai: vải sợi tổng hợp hút ẩm kém nên ít thấm mồ hôi hơn vải bông.", lv: 2 },
      { topic: "Trang phục trong đời sống", type: "mc", q: "Áo blouse trắng của bác sĩ, quân phục của bộ đội cho thấy trang phục còn thể hiện điều gì về người mặc?", o: ["Nghề nghiệp của người mặc", "Tuổi của người mặc", "Quê quán của người mặc", "Chiều cao của người mặc"], x: "Nhìn trang phục đặc trưng của một nghề (áo blouse, quân phục, đồng phục công an…) ta biết ngay nghề nghiệp của người mặc. Trang phục còn thể hiện sở thích, cá tính của người mặc.", lv: 2 },
      { topic: "Trang phục trong đời sống", type: "mc", q: "Bà của Lan có làn da nhạy cảm, hay bị ngứa và sống ở vùng khí hậu nóng. Khi chọn vải may áo cho bà, Lan nên chọn:", o: ["Vải bông (sợi thiên nhiên)", "Vải ni-lông", "Vải pô-li-ét-te", "Vải nhựa"], x: "Vải bông mềm, thoáng mát, thấm mồ hôi, ít gây kích ứng da nên hợp với người da nhạy cảm ở vùng nóng. Vải ni-lông, pô-li-ét-te ít thấm mồ hôi, mặc nóng, dễ gây bí.", lv: 3 },
      { topic: "Trang phục trong đời sống", type: "match", q: "Nối mỗi bộ trang phục với cách phân loại phù hợp.", l: ["Áo khoác dày, khăn len", "Bộ đồng phục của bác bảo vệ", "Váy xòe cho bé gái"], r: ["Phân loại theo thời tiết", "Phân loại theo công dụng", "Phân loại theo giới tính và lứa tuổi", "Phân loại theo giá tiền"], x: "Áo khoác, khăn len là trang phục mùa lạnh (theo thời tiết); đồng phục của bác bảo vệ dùng cho công việc (theo công dụng); váy xòe cho bé gái là trang phục nữ, cho trẻ em (theo giới tính và lứa tuổi). Trang phục không phân loại theo giá tiền.", lv: 3 },
      { topic: "Sử dụng và bảo quản trang phục", type: "mc", q: "Khi lựa chọn trang phục, cần căn cứ vào:", o: ["Vóc dáng, lứa tuổi và hoạt động của người mặc", "Chỉ cần theo mốt mới nhất", "Chỉ cần giá càng đắt càng tốt", "Chỉ cần giống với bạn bè"], x: "Trang phục đẹp khi phù hợp với vóc dáng, lứa tuổi và hoạt động (đi học, lao động, lễ hội, ở nhà…) của người mặc, cùng với điều kiện của gia đình.", lv: 1 },
      { topic: "Sử dụng và bảo quản trang phục", type: "mc", q: "Bảo quản trang phục gồm các công việc:", o: ["Làm sạch, làm khô, làm phẳng, cất giữ", "Cắt, may, thêu, đính cúc", "Mua, thử, trả giá, mang về", "Vẽ mẫu, chọn vải, đo, may"], x: "Bảo quản trang phục gồm làm sạch (giặt), làm khô (phơi, sấy), làm phẳng (là) và cất giữ đúng cách để quần áo bền, đẹp lâu.", lv: 1 },
      { topic: "Sử dụng và bảo quản trang phục", type: "mc", q: "Trên nhãn quần áo, kí hiệu hình bàn là có dấu gạch chéo có nghĩa là:", o: ["Không được là", "Là ở nhiệt độ cao", "Chỉ là bằng hơi nước", "Phải là hằng ngày"], x: "Hình bàn là cho biết việc là; dấu gạch chéo nghĩa là không được. Các chấm trong hình bàn là chỉ mức nhiệt độ là được phép.", lv: 1 },
      { topic: "Sử dụng và bảo quản trang phục", type: "mc", q: "Vì sao trước khi giặt, là một bộ quần áo mới nên đọc kí hiệu trên nhãn của nó?", o: ["Vì mỗi loại vải cần cách giặt, là khác nhau; làm sai có thể làm quần áo hỏng, phai màu", "Vì nhãn ghi giá tiền của bộ quần áo", "Vì nhãn cho biết quần áo may ở đâu", "Vì đọc nhãn thì quần áo sạch hơn"], x: "Nhãn ghi cách bảo quản phù hợp với loại vải: nhiệt độ nước giặt, có được tẩy, sấy, là hay không… Làm đúng nhãn thì quần áo không bị co, phai màu, hỏng.", lv: 2 },
      { topic: "Sử dụng và bảo quản trang phục", type: "mc", q: "Vì sao nên phơi quần áo màu sẫm ở nơi thoáng gió, tránh nắng gắt?", o: ["Để quần áo không bị phai màu", "Để quần áo khô nhanh hơn", "Để quần áo không bị ướt lại", "Để tiết kiệm xà phòng"], x: "Nắng gắt làm thuốc nhuộm bạc đi, quần áo màu sẫm nhanh phai, loang màu. Phơi nơi thoáng gió, tránh nắng gắt giữ màu lâu hơn; quần áo trắng có thể phơi nắng.", lv: 2 },
      { topic: "Sử dụng và bảo quản trang phục", type: "tf4", q: "Mỗi ý sau về cách phối hợp trang phục đúng hay sai?", o: ["Áo có hoa văn to nên mặc với quần vải trơn.", "Nên mặc áo kẻ sọc với quần kẻ ca-rô cho sinh động.", "Màu sẫm và màu nhạt cùng một màu (xanh đậm với xanh nhạt) phối với nhau trông hài hòa.", "Mặc bộ đồ thể thao đi dự lễ tổng kết là hợp lí."], a: [true, false, true, false], x: "a), c) Đúng: vải hoa văn đi với vải trơn, các sắc độ của cùng một màu đi với nhau trông hài hòa. b) Sai: hai loại hoa văn nhiều đường nét mặc cùng nhau trông rối mắt. d) Sai: dự lễ cần trang phục lịch sự, phù hợp hoạt động.", lv: 2 },
      { topic: "Sử dụng và bảo quản trang phục", type: "order", q: "Sắp xếp các bước giặt quần áo bằng tay theo đúng thứ tự.", o: ["Lấy đồ trong túi ra, tách riêng quần áo trắng và quần áo màu", "Ngâm quần áo trong nước có xà phòng", "Vò kĩ các chỗ bẩn như cổ áo, tay áo", "Giũ nhiều lần bằng nước sạch", "Vắt ráo nước rồi phơi"], x: "Giặt tay theo thứ tự: chuẩn bị và phân loại (để quần áo màu không làm loang màu đồ trắng), ngâm, vò, giũ sạch xà phòng, vắt rồi phơi.", lv: 3 },
      { topic: "Sử dụng và bảo quản trang phục", type: "tf4", q: "Hà tự bảo quản bộ đồng phục của mình. Mỗi việc làm sau đúng hay sai?", o: ["Giặt chung áo trắng với chiếc quần màu đậm mới mua.", "Giũ sạch xà phòng trước khi phơi.", "Là áo ở nhiệt độ phù hợp với loại vải.", "Cất áo còn ẩm vào tủ cho kịp giờ đi học."], a: [false, true, true, false], x: "a) Sai: quần màu đậm mới dễ phai, làm loang màu áo trắng. b), c) Đúng: xà phòng còn sót làm vải cứng, ố; là đúng nhiệt độ thì vải không cháy, không nhăn. d) Sai: áo ẩm cất tủ sẽ ẩm mốc, có mùi.", lv: 3 },
      { topic: "Thời trang", type: "mc", q: "Thời trang là:", o: ["Cách ăn mặc, trang điểm phổ biến, được nhiều người ưa chuộng trong một thời gian nhất định", "Những bộ quần áo đắt tiền nhất", "Trang phục chỉ dùng trên sân khấu", "Cách may quần áo bằng máy"], x: "Thời trang là cách ăn mặc, trang điểm phổ biến, được nhiều người ưa chuộng trong xã hội ở một thời gian nhất định.", lv: 1 },
      { topic: "Thời trang", type: "mc", q: "Phong cách thời trang thể thao có đặc điểm:", o: ["Thiết kế đơn giản, đường nét khỏe khoắn, thoải mái khi vận động", "Kiểu dáng cầu kì, nhiều nếp bèo, ren", "Chỉ dùng vải tơ tằm, màu sẫm", "Chỉ mặc khi dự lễ, hội họp"], x: "Phong cách thể thao: kiểu dáng đơn giản, khỏe khoắn, chất liệu co giãn, thấm hút tốt, thuận tiện khi vận động, mặc được hằng ngày.", lv: 1 },
      { topic: "Thời trang", type: "tf4", q: "Mỗi ý sau về thời trang đúng hay sai?", o: ["Thời trang không bao giờ thay đổi theo thời gian.", "Thời trang chỉ dành cho người nổi tiếng.", "Mỗi người có thể chọn phong cách thời trang phù hợp với tính cách, sở thích của mình.", "Có thể phối hợp các trang phục đang có để tạo phong cách riêng, không nhất thiết phải mua mới."], a: [false, false, true, true], x: "a) Sai: thời trang thay đổi theo thời gian. b) Sai: ai cũng có thể ăn mặc hợp thời trang. c), d) Đúng: mỗi người chọn phong cách riêng và có thể tạo phong cách bằng cách phối hợp trang phục sẵn có.", lv: 2 },
      { topic: "Thời trang", type: "mc", q: "Bộ vest màu sẫm, kiểu dáng giản dị, nghiêm túc, lịch sự mà bố mặc đi làm thuộc phong cách thời trang nào?", o: ["Cổ điển", "Thể thao", "Dân gian", "Lãng mạn"], x: "Phong cách cổ điển có kiểu dáng giản dị, nghiêm túc, lịch sự, thường dùng ở nơi làm việc, hội họp.", lv: 2 },
      { topic: "Thời trang", type: "mc", q: "Lan muốn mua một chiếc áo khoác mới. Cách chọn hợp lí nhất là:", o: ["Chọn áo phù hợp với vóc dáng, lứa tuổi, hoàn cảnh sử dụng và điều kiện của gia đình", "Chọn chiếc đắt nhất trong cửa hàng để chắc chắn đẹp", "Chọn đúng kiểu áo của một ca sĩ nổi tiếng dù không hợp với mình", "Chọn chiếc nào bạn thân thích"], x: "Mặc đẹp là mặc phù hợp với bản thân và hoàn cảnh, không phải cứ đắt hay giống người nổi tiếng là đẹp. Cũng cần phù hợp điều kiện của gia đình.", lv: 3 },
      { topic: "Đồ dùng điện trong gia đình", type: "mc", q: "Đồ dùng điện trong gia đình là:", o: ["Sản phẩm công nghệ hoạt động bằng năng lượng điện, phục vụ sinh hoạt gia đình", "Mọi đồ vật có trong nhà", "Dụng cụ làm bằng kim loại", "Đồ dùng chỉ chạy bằng pin"], x: "Đồ dùng điện trong gia đình (quạt, nồi cơm điện, đèn, máy giặt…) là sản phẩm công nghệ dùng năng lượng điện để phục vụ sinh hoạt của gia đình.", lv: 1 },
      { topic: "Đồ dùng điện trong gia đình", type: "num", q: "Trên nhãn một chiếc quạt bàn ghi: 220 V – 45 W. Điện áp định mức của quạt là bao nhiêu vôn?", ans: 220, unit: "V", x: "Số ghi kèm đơn vị V (vôn) là điện áp định mức: 220 V. Số 45 W là công suất định mức.", lv: 1 },
      { topic: "Đồ dùng điện trong gia đình", type: "tf4", q: "Mỗi ý sau về an toàn khi sử dụng đồ dùng điện đúng hay sai?", o: ["Không chạm vào đồ dùng điện, ổ cắm khi tay ướt.", "Cắm nhiều đồ dùng công suất lớn vào cùng một ổ cắm cho tiện.", "Đặt đồ dùng điện ở nơi khô ráo, tránh nước.", "Tự tháo đồ dùng điện ra sửa khi chưa rút phích cắm."], a: [true, false, true, false], x: "a), c) Đúng: nước dẫn điện, tay ướt hay đồ dùng bị ướt dễ gây điện giật. b) Sai: một ổ cắm chịu nhiều đồ dùng công suất lớn dễ quá tải, nóng chảy, cháy. d) Sai: sửa đồ dùng điện phải ngắt điện trước và nên để người lớn, thợ điện làm.", lv: 2 },
      { topic: "Đồ dùng điện trong gia đình", type: "mc", q: "Gia đình Hùng mua ở nước ngoài một máy sấy tóc ghi điện áp định mức 110 V. Điện lưới ở Việt Nam là 220 V. Nếu cắm thẳng máy vào ổ điện trong nhà thì:", o: ["Máy có thể bị cháy, hỏng vì điện áp cao hơn điện áp định mức", "Máy chạy khỏe gấp đôi, rất tốt", "Không sao, mọi đồ dùng điện đều dùng được ở mọi điện áp", "Máy sẽ tự giảm điện áp xuống 110 V"], x: "Máy chỉ chịu được điện áp 110 V. Cắm vào nguồn 220 V cao gấp đôi, máy quá nóng, cháy, hỏng, có thể gây nguy hiểm. Phải dùng bộ đổi điện áp hoặc chọn máy 220 V.", lv: 3 },
      { topic: "Đồ dùng điện trong gia đình", type: "order", q: "Sắp xếp các bước sử dụng bàn là điện an toàn theo đúng thứ tự.", o: ["Kiểm tra dây điện, phích cắm còn tốt", "Cắm điện, chọn mức nhiệt độ phù hợp với loại vải", "Là quần áo, không để bàn là nằm lâu trên vải", "Rút phích cắm, để bàn là nguội hẳn rồi cất"], x: "Trước khi dùng cần kiểm tra dây, phích cắm; khi dùng chọn đúng nhiệt độ và không để bàn là đứng yên trên vải; dùng xong rút phích cắm, chờ nguội mới cất để tránh bỏng, cháy.", lv: 3 }
    ]
  },
  "congnghe6-gk2-de2": {
    note: "Sách Kết nối tri thức, nửa đầu học kì II: Chương III Trang phục và thời trang (Bài 7 Trang phục trong đời sống, Bài 8 Sử dụng và bảo quản trang phục, Bài 9 Thời trang); Chương IV Đồ dùng điện trong gia đình (Bài 10 Khái quát về đồ dùng điện trong gia đình). Có trường học Bài 7 từ cuối học kì I, có trường chỉ kiểm tra đến Bài 9; phụ huynh đối chiếu với đề cương của trường. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Trang phục trong đời sống", type: "mc", q: "Vải sợi tổng hợp (như ni-lông, pô-li-ét-te) được tạo ra từ:", o: ["Than đá, dầu mỏ", "Sợi bông", "Tơ tằm", "Lông cừu"], x: "Sợi tổng hợp được tổng hợp từ than đá, dầu mỏ, thuộc nhóm vải sợi hóa học.", lv: 1 },
      { topic: "Trang phục trong đời sống", type: "mc", q: "Vải sợi nhân tạo (như vải vi-xcô) được làm từ:", o: ["Gỗ, tre, nứa", "Dầu mỏ", "Lông cừu", "Sợi bông"], x: "Sợi nhân tạo được chế biến từ chất xơ của gỗ, tre, nứa; vải sợi nhân tạo thuộc nhóm vải sợi hóa học.", lv: 1 },
      { topic: "Trang phục trong đời sống", type: "mc", q: "Vải sợi pha là vải:", o: ["Được dệt từ hai hay nhiều loại sợi khác nhau", "Được nhuộm nhiều màu khác nhau", "Được may từ nhiều mảnh vải vụn", "Chỉ dệt từ sợi bông"], x: "Vải sợi pha dệt từ sợi pha, kết hợp hai hay nhiều loại sợi (ví dụ bông pha pô-li-ét-te) nên có ưu điểm của các loại sợi thành phần.", lv: 1 },
      { topic: "Trang phục trong đời sống", type: "mc", q: "Vì sao áo mưa, áo gió thường được may bằng vải sợi tổng hợp?", o: ["Vì vải sợi tổng hợp ít thấm nước, bền, nhẹ", "Vì vải sợi tổng hợp thấm mồ hôi rất tốt", "Vì vải sợi tổng hợp đắt tiền hơn", "Vì vải sợi tổng hợp dễ nhàu"], x: "Vải sợi tổng hợp ít thấm nước, bền, nhẹ, nhanh khô nên hợp với áo mưa, áo gió. Chính vì ít thấm nước nên loại vải này thấm mồ hôi kém, không hợp với áo mặc mùa hè.", lv: 2 },
      { topic: "Trang phục trong đời sống", type: "mc", q: "Một chiếc áo may bằng vải bông, kiểu rộng, màu xanh nhạt, in hoa nhỏ. Chi tiết “in hoa nhỏ” thuộc yếu tố nào của trang phục?", o: ["Đường nét, họa tiết", "Chất liệu", "Kiểu dáng", "Giá tiền"], x: "Hoa văn, hình in, đường kẻ trên vải là đường nét, họa tiết của trang phục. Vải bông là chất liệu, kiểu rộng là kiểu dáng, xanh nhạt là màu sắc.", lv: 2 },
      { topic: "Trang phục trong đời sống", type: "mc", q: "Hùng đi dã ngoại ngoài trời nắng cả ngày. Bộ trang phục phù hợp nhất là:", o: ["Áo mỏng, sáng màu, mũ rộng vành, giày thể thao", "Áo khoác dày, khăn len, giày da", "Bộ vest, giày tây", "Áo len, quần nỉ"], x: "Trời nắng nóng cần trang phục mỏng, thoáng, màu sáng ít hấp thụ nhiệt, có mũ che nắng và giày thể thao để đi lại thoải mái. Áo dày, áo len dùng cho mùa lạnh; vest dùng khi dự lễ.", lv: 3 },
      { topic: "Trang phục trong đời sống", type: "tf4", q: "Mẹ mua vải may bộ đồng phục cho Lan mặc đi học suốt năm. Mỗi nhận xét sau đúng hay sai?", o: ["Chọn vải sợi pha vừa thoáng, vừa ít nhàu và bền là hợp lí.", "Chọn vải tơ tằm vì đắt tiền thì chắc chắn bền nhất.", "Vải dễ giặt, nhanh khô phù hợp với đồng phục mặc thường xuyên.", "Chỉ cần đẹp, không cần quan tâm chất liệu vải."], a: [true, false, true, false], x: "a), c) Đúng: đồng phục mặc hằng ngày cần vải bền, thoáng, ít nhàu, dễ giặt. b) Sai: tơ tằm đẹp nhưng mỏng, dễ hỏng, khó giặt, không hợp mặc đi học. d) Sai: chất liệu quyết định độ bền và cảm giác dễ chịu khi mặc.", lv: 3 },
      { topic: "Sử dụng và bảo quản trang phục", type: "mc", q: "Giặt khô là cách làm sạch quần áo:", o: ["Bằng hóa chất chuyên dụng, không dùng nước", "Bằng cách phơi nắng thật lâu", "Bằng nước nóng và xà phòng", "Bằng cách là ở nhiệt độ cao"], x: "Giặt khô dùng hóa chất chuyên dụng thay cho nước, thường làm ở tiệm giặt, dành cho quần áo không giặt nước được (vest, áo len cao cấp…).", lv: 1 },
      { topic: "Sử dụng và bảo quản trang phục", type: "mc", q: "Trang phục may bằng vải mềm, mỏng, kiểu ôm sát cơ thể tạo cảm giác người mặc:", o: ["Gầy đi, cao lên", "Béo ra, thấp xuống", "Già đi", "Khỏe mạnh hơn"], x: "Vải mềm, mỏng, kiểu ôm vừa người làm người mặc trông thon gọn, cao hơn; vải dày, cứng, kiểu thụng, tay bồng tạo cảm giác béo ra, thấp xuống.", lv: 1 },
      { topic: "Sử dụng và bảo quản trang phục", type: "mc", q: "Trên nhãn quần áo, kí hiệu hình chậu nước có ghi số 40 nghĩa là:", o: ["Giặt bằng nước có nhiệt độ không quá 40 °C", "Giặt trong 40 phút", "Giặt 40 lần thì bỏ", "Dùng 40 g xà phòng"], x: "Hình chậu nước là kí hiệu giặt bằng nước; số ghi trong chậu là nhiệt độ nước tối đa (°C) được phép giặt.", lv: 1 },
      { topic: "Sử dụng và bảo quản trang phục", type: "mc", q: "Lan hơi gầy, muốn trông đầy đặn hơn. Lan nên chọn áo:", o: ["Màu sáng, kẻ sọc ngang, họa tiết hoa to", "Màu sẫm, kẻ sọc dọc, ôm sát", "Màu đen, vải mỏng, bó sát", "Màu tối, trơn, ôm vừa người"], x: "Màu sáng, kẻ ngang, hoa to, kiểu rộng tạo cảm giác đầy đặn hơn, hợp với người gầy.", lv: 2 },
      { topic: "Sử dụng và bảo quản trang phục", type: "mc", q: "Vì sao trang phục đi lao động nên là quần áo tối màu, vải dày, dễ giặt?", o: ["Vì khi lao động quần áo dễ bẩn, dễ rách nên cần bền, ít lộ vết bẩn, giặt được nhiều lần", "Vì màu tối giúp người mặc đẹp hơn", "Vì vải dày giúp mát hơn khi làm việc", "Vì quần áo tối màu rẻ hơn"], x: "Lao động làm quần áo bẩn và dễ sờn rách, nên chọn vải dày, bền, màu tối ít lộ bẩn, dễ giặt. Trang phục lao động ưu tiên bền, tiện, an toàn hơn là đẹp.", lv: 2 },
      { topic: "Sử dụng và bảo quản trang phục", type: "tf", q: "Quần áo chưa dùng đến trong thời gian dài nên giặt sạch, gói kín và để nơi khô ráo để tránh ẩm mốc.", a: true, x: "Đúng. Quần áo dùng thường xuyên thì treo hoặc gấp gọn trong tủ; quần áo chưa dùng đến (trái mùa) cần giặt sạch, gói kín, để nơi khô ráo để không bị ẩm mốc, gián cắn.", lv: 2 },
      { topic: "Sử dụng và bảo quản trang phục", type: "match", q: "Nối mỗi kí hiệu trên nhãn quần áo với ý nghĩa của nó.", l: ["Hình tam giác có gạch chéo", "Hình vuông có vòng tròn bên trong", "Hình tròn"], r: ["Không được tẩy", "Sấy được bằng máy", "Giặt khô", "Phải giặt bằng nước nóng"], x: "Hình tam giác là kí hiệu tẩy, có gạch chéo là không được tẩy; hình vuông có vòng tròn là sấy bằng máy; hình tròn là giặt khô. Giặt bằng nước được kí hiệu bằng hình chậu nước.", lv: 3 },
      { topic: "Sử dụng và bảo quản trang phục", type: "mc", q: "Nam cao, hơi béo, muốn trông gọn hơn khi đi dự sinh nhật bạn. Nam nên chọn:", o: ["Áo màu sẫm, kẻ sọc dọc, kiểu vừa người", "Áo màu sáng, kẻ sọc ngang, kiểu thụng", "Áo hoa to, tay bồng", "Áo trắng kẻ ngang, quần rộng thùng thình"], x: "Màu sẫm, kẻ dọc, kiểu vừa người tạo cảm giác gọn, thon hơn; kiểu thụng, tay bồng làm người mặc trông to hơn.", lv: 3 },
      { topic: "Thời trang", type: "mc", q: "Phong cách thời trang mang đặc trưng của trang phục dân tộc về văn hóa, chất liệu, kiểu dáng là phong cách:", o: ["Dân gian", "Cổ điển", "Thể thao", "Lãng mạn"], x: "Phong cách dân gian lấy cảm hứng từ trang phục truyền thống của các dân tộc: chất liệu, hoa văn, kiểu dáng mang nét văn hóa dân tộc.", lv: 1 },
      { topic: "Thời trang", type: "mc", q: "Trang phục có nhiều đường cong, nếp bèo, uốn lượn, tạo cảm giác nhẹ nhàng, mềm mại thuộc phong cách:", o: ["Lãng mạn", "Thể thao", "Cổ điển", "Dân gian"], x: "Phong cách lãng mạn dùng các đường cong, đường uốn lượn, nếp bèo, màu nhẹ, tạo vẻ nhẹ nhàng, mềm mại.", lv: 1 },
      { topic: "Thời trang", type: "mc", q: "Vì sao thời trang thay đổi theo thời gian?", o: ["Vì đời sống, thị hiếu của con người và kĩ thuật dệt may thay đổi", "Vì vải ngày càng đắt", "Vì mọi người đều muốn giống nhau", "Vì quần áo cũ không giặt được"], x: "Mỗi thời kì, con người có điều kiện sống, sở thích khác nhau; kĩ thuật dệt, may, chất liệu mới cũng xuất hiện, nên cách ăn mặc được ưa chuộng thay đổi theo.", lv: 2 },
      { topic: "Thời trang", type: "mc", q: "Phong cách thời trang của một người được thể hiện qua:", o: ["Kiểu dáng, màu sắc, chất liệu của những trang phục người đó thường mặc", "Số tiền người đó bỏ ra mua quần áo", "Số lượng quần áo trong tủ", "Tên cửa hàng người đó hay mua"], x: "Phong cách thời trang là nét riêng trong cách ăn mặc, thể hiện qua kiểu dáng, màu sắc, chất liệu, cách phối hợp trang phục mà một người thường chọn; không phụ thuộc vào số tiền hay số lượng quần áo.", lv: 2 },
      { topic: "Thời trang", type: "mc", q: "Lớp tổ chức buổi biểu diễn thời trang chủ đề “Nét đẹp truyền thống Việt Nam”. Trang phục phù hợp nhất để Mai mặc là:", o: ["Áo dài", "Bộ đồ thể thao", "Váy dạ hội nhiều tầng bèo", "Quần bò, áo phông"], x: "Áo dài là trang phục truyền thống của Việt Nam, đúng với chủ đề nét đẹp truyền thống. Đồ thể thao, váy dạ hội, quần bò áo phông không thể hiện nét truyền thống.", lv: 3 },
      { topic: "Đồ dùng điện trong gia đình", type: "mc", q: "Thông số kĩ thuật của đồ dùng điện gồm:", o: ["Các đại lượng điện định mức chung và các đại lượng riêng theo chức năng của đồ dùng", "Chỉ có giá tiền và tên hãng", "Chỉ có màu sắc và kích thước hộp", "Chỉ có năm sản xuất"], x: "Thông số kĩ thuật gồm các đại lượng định mức chung (điện áp định mức, công suất định mức) và đại lượng đặc trưng riêng cho chức năng (dung tích nồi cơm điện, đường kính cánh quạt…), do nhà sản xuất quy định.", lv: 1 },
      { topic: "Đồ dùng điện trong gia đình", type: "mc", q: "Điện áp định mức của một đồ dùng điện là:", o: ["Mức điện áp để đồ dùng hoạt động bình thường và an toàn", "Điện áp lớn nhất mà đồ dùng chịu được trước khi cháy", "Số tiền điện phải trả mỗi tháng", "Thời gian đồ dùng chạy được trong một ngày"], x: "Điện áp định mức (đơn vị vôn, V) là mức điện áp mà nhà sản xuất quy định để đồ dùng hoạt động bình thường, an toàn. Dùng sai điện áp, đồ dùng có thể hỏng.", lv: 1 },
      { topic: "Đồ dùng điện trong gia đình", type: "mc", q: "Trên nhãn nồi cơm điện ghi công suất định mức 700 W. Con số này cho biết:", o: ["Mức tiêu thụ điện năng của nồi khi hoạt động ở điện áp định mức", "Số bát cơm nồi nấu được", "Thời gian nấu một nồi cơm", "Khối lượng của nồi"], x: "Công suất định mức (đơn vị oát, W) thể hiện mức tiêu thụ điện năng của đồ dùng khi hoạt động ở điện áp định mức: công suất càng lớn, dùng càng lâu thì tốn càng nhiều điện.", lv: 2 },
      { topic: "Đồ dùng điện trong gia đình", type: "mc", q: "Nhà Lan có 6 người, muốn mua nồi cơm điện mới. Khi chọn nồi, cần quan tâm trước hết đến:", o: ["Dung tích nồi đủ cho 6 người, điện áp định mức 220 V và nơi bán tin cậy", "Nồi có màu hợp với màu tường bếp", "Nồi có nhiều nút bấm nhất", "Nồi rẻ nhất, không cần xem thông số"], x: "Chọn đồ dùng điện cần xem thông số phù hợp nhu cầu (dung tích đủ cho số người ăn), đúng điện áp của điện lưới nước ta (220 V), có tiết kiệm điện, mua ở nơi tin cậy và hợp với điều kiện gia đình.", lv: 3 },
      { topic: "Đồ dùng điện trong gia đình", type: "mc", q: "Nam thấy dây điện của chiếc quạt bị hở, lộ lõi đồng. Nam nên:", o: ["Không dùng quạt, rút phích cắm và báo người lớn sửa hoặc thay dây", "Lấy băng dính giấy quấn tạm rồi dùng tiếp", "Vẫn dùng vì quạt còn quay", "Tự tách dây ra xem khi quạt đang chạy"], x: "Dây hở có thể gây điện giật, chập cháy. Phải ngừng dùng, rút phích cắm và nhờ người lớn, thợ điện thay dây hoặc sửa; không tự sửa khi chưa có người lớn và nhất là khi quạt đang cắm điện.", lv: 3 }
    ]
  }
});
